101	// registryFilterLabel returns a short display label for the active filter.
102	//
103	// D14: it used to search only the configured top-level entries, so filtering to
104	// a discovered member fell through to the synthesised URL — the one row in the
105	// view showing a URL where every other showed an alias. Members are entries now,
106	// so they resolve like anything else.
107	func (b *RegistryBrowser) registryFilterLabel() string {
108		if b.registryFilter.groupSlug != "" {
109			for _, reg := range b.registries {
