160	// normalizeRepoForRegistry prepends "library/" for bare names on Docker Hub.
161	func normalizeRepoForRegistry(registryURL, repo string) string {
162		if strings.Contains(repo, "/") {
163			return repo
164		}
165		if isDockerHub(registryURL) {
166			return "library/" + repo
167		}
168		return repo
169	}
170	
171	// registryHost strips the scheme from a configured registry URL, leaving what
172	// Docker itself is keyed on: `host[:port]`, plus whatever path a repository
173	// manager serves the registry under.
174	//
175	// A registry URL is written either way in practice — the form does not
176	// normalize it, `registryAPIURL` explicitly accepts both, and this package's own
177	// examples write `https://nexus.example.com/repository/docker-group`. Every
178	// Docker-facing use has to strip it, and none of the three that needed to did
179	// (D39): a `docker pull` reference carrying `https://` is not a reference at
180	// all, and a hub alias compared against a scheme-bearing string never matched,
181	// so images from a Hub configured as `https://docker.io` lost their `library/`
182	// prefix.
183	func registryHost(registryURL string) string {
184		base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
185		for _, scheme := range []string{"https://", "http://"} {
186			if len(base) >= len(scheme) && strings.EqualFold(base[:len(scheme)], scheme) {
187				return base[len(scheme):]
188			}
189		}
190		return base
191	}
192	
193	// isDockerHub reports whether a registry URL names Docker Hub, under either of
194	// the two spellings and with or without a scheme. Hub is the one registry whose
195	// references carry no host, so every caller has to recognise it.
196	func isDockerHub(registryURL string) bool {
197		host := registryHost(registryURL)
198		return strings.EqualFold(host, "docker.io") || strings.EqualFold(host, "registry-1.docker.io")
199	}
200	
201	// multiImageName constructs the full image reference for pull/scan.
202	func multiImageName(registryURL, repo, tag string) string {
203		if isDockerHub(registryURL) {
204			return repo + ":" + tag
205		}
206		return registryHost(registryURL) + "/" + repo + ":" + tag
207	}
