216	// filteredSortedMultiTags returns tags after applying registry filter, text filter, and sort.
217	func (b *RegistryBrowser) filteredSortedMultiTags() []MultiRegistryTag {
218		query := strings.ToLower(b.filterInput.Value())
219		var result []MultiRegistryTag
220		for _, t := range b.tags {
221			if !b.registryFilter.matches(t.RegistryURL, b.entryFor(t.RegistryURL)) {
222				continue
223			}
224			if query != "" && !strings.Contains(strings.ToLower(t.Tag), query) &&
225				!strings.Contains(strings.ToLower(t.Repo), query) {
226				continue
227			}
228			result = append(result, t)
229		}
230	
231		sortCol := b.tagSortCol
232		sortDesc := b.tagSortDesc
233		sort.SliceStable(result, func(i, j int) bool {
234			var less bool
235			switch sortCol {
236			case tagSortByUpdated:
237				less = result[i].UpdatedAt.After(result[j].UpdatedAt)
238			default:
239				less = strings.ToLower(result[i].Tag) < strings.ToLower(result[j].Tag)
240			}
241			if sortDesc {
242				return !less
243			}
244			return less
245		})
246		return result
247	}
