14	// rebuildTagTable rebuilds the results table rows with current filter/sort/CVE data.
15	func (b *RegistryBrowser) rebuildTagTable() {
16		displayed := b.filteredSortedMultiTags()
17		rows := make([]table.Row, len(displayed))
18		for i, t := range displayed {
19			imageName := multiImageName(t.RegistryURL, t.Repo, t.Tag)
20	
21			registryLabel := t.Alias
22			if registryLabel == "" {
23				registryLabel = t.RegistryURL
24			}
25	
26			updated := "-"
27			if !t.UpdatedAt.IsZero() {
28				updated = theme.TimeAgo(t.UpdatedAt)
29			}
30	
31			crit, high, med, low := "-", "-", "-", "-"
32			if b.scanningTags[imageName] {
33				frame := spinner.Dot.Frames[b.tagScanSpinnerIdx%len(spinner.Dot.Frames)]
34				crit, high, med, low = frame, frame, frame, frame
35			} else if entry, ok := b.scanCache[imageName]; ok {
36				crit = fmt.Sprintf("%d", entry.Critical)
37				high = fmt.Sprintf("%d", entry.High)
38				med = fmt.Sprintf("%d", entry.Medium)
39				low = fmt.Sprintf("%d", entry.Low)
40			}
41	
42			rows[i] = table.Row{registryLabel, t.Tag, updated, crit, high, med, low}
43		}
44	
45		cols := b.tagTable.Columns()
46		if len(cols) == 7 {
47			cols[1].Title = "Tag"
48			cols[2].Title = "Updated"
49			switch b.tagSortCol {
