66	func (b *RegistryBrowser) handleKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
67		switch b.state {
68		case browserStateInput:
69			return b.handleInputKeyMsg(msg)
70		case browserStateTags:
71			return b.handleTagsKeyMsg(msg)
72		case browserStateStatus:
73			return b, nil
74		}
75		return b, nil
76	}
